import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, step, sub, add, mul, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DirectionalLight, AmbientLight } = THREE;

  const root = new Group();
  root.name = 'bento-metrics-grid';

  const vs = config.intent?.visualSpec ?? {};
  const colors = vs.colors ?? {};
  const accentHex = colors.accent || '#ff2a38';
  const paperHex = colors.paper || '#e8ecf2';
  const stops = colors.gradientStops ?? [{ at: 0, hex: '#101017' }, { at: 1, hex: '#1a1a22' }];
  const c0 = stops[0].hex;
  const c1 = stops[stops.length - 1].hex;

  // ---------- Backdrop (stage, never void) ----------
  const backdropMat = new MeshBasicNodeMaterial();
  const buv = uv();
  backdropMat.colorNode = mix(vec3(c0), vec3(c1), buv.y);
  const backdrop = new Mesh(new PlaneGeometry(7.5, 6), backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---------- Lights (product-shot grade) ----------
  root.add(new AmbientLight(0xffffff, 0.6));
  const key = new DirectionalLight(0xffffff, 1.2);
  key.position.set(3, 3.5, 5);
  root.add(key);
  const rim = new DirectionalLight(0xff5560, 0.6);
  rim.position.set(-4, -1, -3);
  root.add(rim);
  const fill = new DirectionalLight(0xe8ecf2, 0.3);
  fill.position.set(-3, 2, 4);
  root.add(fill);

  // ---------- Cell material (engineered gradient + machined sheen) ----------
  function makeCellMaterial() {
    const mat = new MeshPhysicalNodeMaterial();
    mat.metalness = 0.45;
    mat.roughness = 0.5;
    mat.clearcoat = 0.2;
    mat.clearcoatRoughness = 0.4;
    const cuv = uv();
    const diag = add(cuv.x, cuv.y).mul(0.5);
    const grad = mix(vec3(c0), vec3(c1), diag);
    // hard-stop sheen band 0.15 wide centered at 0.40 of diagonal, +6% value
    const inBand = step(float(0.325), diag).mul(sub(float(1.0), step(float(0.475), diag)));
    const sheen = inBand.mul(0.06);
    mat.colorNode = add(grad, vec3(sheen, sheen, sheen));
    return mat;
  }

  // shared tick bar geometry + material (accent emissive read)
  const tickGeo = new PlaneGeometry(0.4, 0.05);
  const tickMat = new MeshBasicNodeMaterial();
  tickMat.colorNode = vec3(accentHex).mul(1.3);

  function makeCell(w, h) {
    const geo = new BoxGeometry(w, h, 0.06);
    return new Mesh(geo, makeCellMaterial());
  }

  // ---------- Layout ----------
  // Dominant: 3.25 x 3.5, left column, both rows
  const dom = makeCell(3.25, 3.5);
  dom.position.set(-1.125, 0, 0);
  root.add(dom);
  // Top-right secondary: 2.0 x 1.625
  const tr = makeCell(2.0, 1.625);
  tr.position.set(1.75, 0.9375, 0);
  root.add(tr);
  // Bottom-right secondary: 2.0 x 1.625
  const br = makeCell(2.0, 1.625);
  br.position.set(1.75, -0.9375, 0);
  root.add(br);

  // ---------- Text ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const T = items.length ? items : [
    { text: 'ATELIER METRICS / Q2 2026', role: 'caption' },
    { text: '0.002 mm', role: 'valueLarge' },
    { text: 'Case tolerance, CNC pass', role: 'label' },
    { text: '38 h', role: 'value' },
    { text: 'Power reserve, NA-01', role: 'label' },
    { text: '214', role: 'value' },
    { text: 'Components per calibre', role: 'label' },
  ];

  const labelColor = '#9aa0ad';

  // Header caption above grid, left-aligned to grid edge
  const header = ctx.fontAtlas.createText(T[0].text, {
    fontSize: 0.14, color: paperHex, align: 'left', letterSpacingPx: 0.012
  });
  header.position.set(-2.75, 2.25, 0.1);
  root.add(header);

  // --- Dominant cell contents (local to box center) ---
  const domTick = new Mesh(tickGeo, tickMat);
  domTick.position.set(-0.925, 1.2, 0.035);
  dom.add(domTick);

  const domValue = ctx.fontAtlas.createText(T[1].text, {
    fontSize: 0.62, color: paperHex, align: 'left'
  });
  domValue.position.set(-1.125, 0.72, 0.04);
  dom.add(domValue);

  const domLabel = ctx.fontAtlas.createText(T[2].text, {
    fontSize: 0.15, color: labelColor, align: 'left', letterSpacingPx: 0.008, maxWidthPx: 2.2
  });
  domLabel.position.set(-1.125, 0.18, 0.04);
  dom.add(domLabel);

  // --- Top-right cell contents ---
  const trTick = new Mesh(tickGeo, tickMat);
  trTick.position.set(-0.3, 0.3, 0.035);
  tr.add(trTick);

  const trValue = ctx.fontAtlas.createText(T[3].text, {
    fontSize: 0.34, color: paperHex, align: 'left'
  });
  trValue.position.set(-0.5, -0.02, 0.04);
  tr.add(trValue);

  const trLabel = ctx.fontAtlas.createText(T[4].text, {
    fontSize: 0.14, color: labelColor, align: 'left', letterSpacingPx: 0.008, maxWidthPx: 1.8
  });
  trLabel.position.set(-0.5, -0.28, 0.04);
  tr.add(trLabel);

  // --- Bottom-right cell contents ---
  const brTick = new Mesh(tickGeo, tickMat);
  brTick.position.set(-0.3, 0.3, 0.035);
  br.add(brTick);

  const brValue = ctx.fontAtlas.createText(T[5].text, {
    fontSize: 0.34, color: paperHex, align: 'left'
  });
  brValue.position.set(-0.5, -0.02, 0.04);
  br.add(brValue);

  const brLabel = ctx.fontAtlas.createText(T[6].text, {
    fontSize: 0.14, color: labelColor, align: 'left', letterSpacingPx: 0.008, maxWidthPx: 1.8
  });
  brLabel.position.set(-0.5, -0.28, 0.04);
  br.add(brLabel);

  // ---------- Entrance: stagger-cards, fade-up, dominant first ----------
  const timelines = [];
  const cells = [
    { mesh: dom, baseY: 0 },
    { mesh: tr, baseY: 0.9375 },
    { mesh: br, baseY: -0.9375 },
  ];
  cells.forEach((c, i) => {
    c.mesh.position.y = c.baseY + 0.2;
    c.mesh.material.transparent = true;
    c.mesh.material.opacity = 0;
    const kids = c.mesh.children;
    for (let k = 0; k < kids.length; k++) kids[k].visible = false;
    const tl = gsap.timeline({ delay: i * 0.08 });
    tl.to(c.mesh.position, { y: c.baseY, duration: 0.5, ease: 'power2.out' }, 0)
      .to(c.mesh.material, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0)
      .add(() => { for (let k = 0; k < kids.length; k++) kids[k].visible = true; }, 0.18);
    timelines.push(tl);
  });

  // Header fade-up
  header.material.transparent = true;
  header.material.opacity = 0;
  header.position.y = 2.45;
  const htl = gsap.timeline({ delay: 0.32 });
  htl.to(header.material, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
  htl.to(header.position, { y: 2.25, duration: 0.5, ease: 'power2.out' }, 0);
  timelines.push(htl);

  // ---------- Hover: press-down + weighted-settle ----------
  function attachHover(target) {
    target.userData.handlers = {
      pointerenter: () => {
        gsap.killTweensOf(target.scale);
        gsap.to(target.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.in(2)' });
      },
      pointerleave: () => {
        gsap.killTweensOf(target.scale);
        gsap.to(target.scale, {
          x: 1.04, y: 1.04, z: 1.04, duration: 0.45, ease: 'power4.out',
          onComplete: () => {
            gsap.to(target.scale, { x: 1, y: 1, z: 1, duration: 0.45, ease: 'power4.out' });
          }
        });
      }
    };
  }
  attachHover(dom);
  attachHover(tr);
  attachHover(br);

  root.userData.handlers = {};

  // ---------- Cleanup ----------
  const allText = [header, domValue, domLabel, trValue, trLabel, brValue, brLabel];
  root.userData.cleanup = () => {
    timelines.forEach(t => t.kill());
    gsap.killTweensOf(dom.scale);
    gsap.killTweensOf(tr.scale);
    gsap.killTweensOf(br.scale);
    [backdropMat, dom.material, tr.material, br.material, tickMat].forEach(m => { try { m.dispose(); } catch (e) {} });
    [backdrop.geometry, dom.geometry, tr.geometry, br.geometry, tickGeo].forEach(g => { try { g.dispose(); } catch (e) {} });
    allText.forEach(t => {
      t.traverse(o => {
        if (o.geometry) { try { o.geometry.dispose(); } catch (e) {} }
        if (o.material) { try { o.material.dispose(); } catch (e) {} }
      });
    });
  };

  return root;
}
